import { Injectable } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { IsNull, type Repository } from "typeorm";
import { EntityRepository, type IUpdatableRepository } from "#/database/base/entity-repository.ts";
import { WebsitesEntity } from "#/modules/source/schema/entities/websites.entity.ts";
import * as Websites from "#/modules/source/schema/types/websites/index.ts";

/**
 * Repository of Websites: the base repository configured with the entity's
 * generated query fields. Regenerated by Dryv; the feature repositories build the contract's
 * named queries on top of it.
 */
@Injectable()
export class WebsitesRepository
  extends EntityRepository<
    WebsitesEntity,
    Websites.Types.WebsitesSortableField,
    Websites.Types.WebsitesEditableField,
    Websites.Types.WebsitesSelectableField,
    Websites.Types.IWebsitesCreatable
  >
  implements IUpdatableRepository<WebsitesEntity, Websites.Types.IWebsitesUpdatable>
{
  constructor(
    @InjectRepository(WebsitesEntity)
    repository: Repository<WebsitesEntity>,
  ) {
    super(repository, Websites.Config.WEBSITES_QUERY_OPTIONS);
  }

  /** Updates a row from only the editable fields of `data`. */
  async updateEditable(
    id: string,
    data: Websites.Types.IWebsitesUpdatable,
  ): Promise<WebsitesEntity | null> {
    const stamped = await this.stampUpdate(id, data);
    return stamped === null ? null : await this.update(id, stamped);
  }

  /** Find the websites with this canonical url (unique). */
  async findByCanonicalUrl(
    canonicalUrl: NonNullable<WebsitesEntity["canonicalUrl"]>,
  ): Promise<WebsitesEntity | null> {
    return await this.findOne({ canonicalUrl, deletedAt: IsNull() });
  }

  /** Find the websites with this source id (unique). */
  async findBySource(
    sourceId: NonNullable<WebsitesEntity["sourceId"]>,
  ): Promise<WebsitesEntity | null> {
    return await this.findOne({ sourceId, deletedAt: IsNull() });
  }
}
